/*
 * A130138  Triangle read by rows: T(n,k) is the number of Fibonacci binary
 *          words of length n and having k 1011's (n>=0,
 *          0<=k<=floor((n-1)/3)). A Fibonacci binary word is a binary word
 *          having no 00 subword.
 * https://oeis.org/A130138
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(n) = sum over k of the number of Fibonacci binary words of *
 *            length n having exactly k occurrences of 1011, read row‑by‑row.
 *            * The triangle T(n,k) is generated by dynamic programming over
 *            the last * three bits and the current count of 1011 patterns
 * Range:     u8 n <= 32, u16 n <= 64, u32 n <= 64, u64 n <= 64, u128 n <= 64,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* --- allocation helpers that work both in C and C++ ------------------- */
#ifdef __cplusplus
#  define ALLOC_SEQ(count)  new seq_t[count]()
#  define FREE_SEQ(ptr)     delete[] ptr
#else
#  define ALLOC_SEQ(count)  ((seq_t*)calloc((count), sizeof(seq_t)))
#  define FREE_SEQ(ptr)     free(ptr)
#endif

/* --- static state for the lazy global computation -------------------- */
static seq_t *flat = NULL;          /* flattened triangle values   */
static idx_t  flat_len = 0;         /* number of values stored     */
static size_t flat_cap = 0;         /* capacity of `flat`          */

static seq_t *dpPrev = NULL;        /* previous row (length = last_row) */
static seq_t *dpCur  = NULL;        /* temporary row (length = last_row+1) */
static size_t stride = 0;           /* current max_k + 1             */
static idx_t  last_row = (idx_t)(-1); /* highest row that has been computed */

/* --- grow the flat array -------------------------------------------- */
static void grow_flat(idx_t *current_len,
                      size_t need, size_t *cap, seq_t **arr)
{
    if (*current_len + need > *cap) {
        size_t newcap = (*cap == 0) ? 1 : *cap;
        while (newcap < *current_len + need) newcap <<= 1;
#ifdef __cplusplus
        seq_t *newarr = ALLOC_SEQ(newcap);
        for (size_t i = 0; i < *current_len; ++i) newarr[i] = (*arr)[i];
        FREE_SEQ(*arr);
#else
        seq_t *newarr = (seq_t*)realloc(*arr, newcap * sizeof(seq_t));
#endif
        *arr = newarr;
        *cap = newcap;
    }
}

/* --- ensure that DP arrays have at least `required_stride` columns -------- */
static void ensure_stride(size_t required_stride)
{
    if (required_stride <= stride) return;

    size_t newsize = 8 * required_stride;
    seq_t *newPrev = NULL;
    seq_t *newCur  = NULL;

#ifdef __cplusplus
    newPrev = ALLOC_SEQ(newsize);
    newCur  = ALLOC_SEQ(newsize);
#else
    newPrev = (seq_t*)calloc(newsize, sizeof(seq_t));
    newCur  = (seq_t*)calloc(newsize, sizeof(seq_t));
#endif

    /* copy old data into new structures */
    if (dpPrev != NULL) {
        for (size_t s = 0; s < 8; ++s)
            for (size_t k = 0; k < stride; ++k)
                newPrev[s * required_stride + k] = dpPrev[s * stride + k];
    }
    if (dpCur != NULL) {
        for (size_t s = 0; s < 8; ++s)
            for (size_t k = 0; k < stride; ++k)
                newCur[s * required_stride + k] = dpCur[s * stride + k];
    }

    FREE_SEQ(dpPrev);
    FREE_SEQ(dpCur);
    dpPrev = newPrev;
    dpCur  = newCur;
    stride = required_stride;
}

/* --- append the next row of the triangle ----------------------------- */
static void add_next_row(void)
{
    size_t cur_len   = (size_t)last_row;      /* word length of dpPrev    */
    size_t next_len  = cur_len + 1;
    size_t maxK_next = (next_len == 0) ? 0 : (next_len - 1) / 3;
    size_t next_stride = maxK_next + 1;

    /* make sure DP arrays can accommodate the new stride */
    ensure_stride(next_stride);

    /* clear new state */
    for (size_t s = 0; s < 8; ++s)
        for (size_t k = 0; k < stride; ++k)
            dpCur[s * stride + k] = 0;

    /* transition from dpPrev to dpCur */
    for (size_t s = 0; s < 8; ++s) {
        size_t basePrev = s * stride;
        for (size_t k = 0; k < stride; ++k) {
            seq_t val = dpPrev[basePrev + k];
            if (!val) continue;

            /* append a '1' */
            size_t t1  = ((s << 1) | 1) & 7;
            size_t nk1 = k + ((s == 5) ? 1 : 0);  /* '1011' formed when last 3 bits were 101 */
            if (nk1 < stride)
                dpCur[t1 * stride + nk1] += val;

            /* append a '0' (allowed if last bit is 1 or this is the first bit) */
            if (cur_len == 0 || (s & 1) != 0) {
                size_t t0 = ((s << 1) | 0) & 7;
                if (k < stride)
                    dpCur[t0 * stride + k] += val;
            }
        }
    }

    /* collect the sums for the new row and add to the flat array */
    size_t row_count = maxK_next + 1;
    grow_flat(&flat_len, row_count, &flat_cap, &flat);
    for (size_t k = 0; k < row_count; ++k) {
        seq_t sum = 0;
        for (size_t s = 0; s < 8; ++s)
            sum += dpCur[s * stride + k];
        flat[flat_len++] = sum;
    }

    /* swap dpPrev and dpCur for the next iteration */
    seq_t *tmp = dpPrev;
    dpPrev = dpCur;
    dpCur  = tmp;

    last_row = (idx_t)next_len;
}

/* --- lazily ensure that the triangle has been built up to index n ------- */
static void ensure_flat_size(idx_t n)
{
    while (flat_len <= n) {
        if (last_row == (idx_t)(-1)) {
            /* initialise first row (length 0) */
            stride = 1;
            dpPrev = ALLOC_SEQ(8 * stride);
            dpCur  = ALLOC_SEQ(8 * stride);
            dpPrev[0] = 1;                 /* T(0,0) = 1 */
            grow_flat(&flat_len, 1, &flat_cap, &flat);
            flat[flat_len++] = 1;
            last_row = 0;
        } else {
            add_next_row();
        }
    }
}

/* ----------------------------------------------------------------------- */
/* public function required by the OEIS harness */
seq_t a(idx_t n)
{
    ensure_flat_size(n);
    return flat[n];
}
